CREATE TABLE IF NOT EXISTS assets (key TEXT PRIMARY KEY, tier TEXT NOT NULL CHECK (tier IN ('public','company')), type TEXT NOT NULL, size INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, tool TEXT NOT NULL, code TEXT NOT NULL, ver TEXT, ua TEXT);
CREATE INDEX IF NOT EXISTS logs_at ON logs(at);
CREATE TABLE IF NOT EXISTS fb_page_map (page_id TEXT PRIMARY KEY, code TEXT, label TEXT, utm TEXT, sort INTEGER, updated INTEGER);
CREATE TABLE IF NOT EXISTS fb_comments (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id TEXT NOT NULL, post_id TEXT, photo_id TEXT, message TEXT NOT NULL, due INTEGER NOT NULL, next_check INTEGER NOT NULL, step INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', error TEXT, comment_id TEXT, dismissed INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL, seq INTEGER NOT NULL DEFAULT 1, delay INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS fb_comments_check ON fb_comments(status, next_check);
CREATE INDEX IF NOT EXISTS fb_comments_post ON fb_comments(post_id);
CREATE TABLE IF NOT EXISTS fb_comment_presets (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, text TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL);
